head.script:
window.dataLayer=window.dataLayer||[];
function gtag(){window.dataLayer.push(arguments);}
(function(){
  const q=new URLSearchParams(location.search);
  let owner=false;
  try{
    if(q.get('utilityra_owner')==='exclude')localStorage.setItem('ur-owner-exclude','1');
    if(q.get('utilityra_owner')==='include')localStorage.removeItem('ur-owner-exclude');
    owner=localStorage.getItem('ur-owner-exclude')==='1';
  }catch(e){}
  const review=q.has('utilityra_review')||q.has('preview')||navigator.webdriver||/bot|crawler|spider|headless|playwright|puppeteer|lighthouse|google-inspectiontool|chatgpt|openai|anthropic|claude|perplexity|gemini|bingpreview/i.test(navigator.userAgent);
  if(!owner&&!review){gtag('js',new Date());gtag('config','G-RVP9Q52085');}
  if(q.has('utilityra_owner')){q.delete('utilityra_owner');const clean=location.pathname+(q.toString()?'?'+q.toString():'')+location.hash;history.replaceState(null,'',clean);}
})();

head.b:skin:
:root{color-scheme:light;--bg:#f5f7fb;--surface:#fff;--ink:#141a32;--muted:#68718a;--line:#e3e7f0;--brand:#6558e8;--brand-dark:#4d40cf;--mint:#d9fbef;--hero:#111831;--shadow:0 18px 55px rgba(25,32,70,.08);--radius:22px}
*{box-sizing:border-box}html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.7 system-ui,-apple-system,"Segoe UI",Arial,sans-serif}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #a5b4fc;outline-offset:3px}.ur-wrap{width:min(1160px,calc(100% - 32px));margin-inline:auto}.ur-top{background:#0b1025;color:#cdd3e8;font-size:12px}.ur-top .ur-wrap{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 0}.ur-top strong{color:#fff}.ur-header{position:sticky;top:0;z-index:40;background:rgba(255,255,255,.92);backdrop-filter:blur(16px);border-bottom:1px solid var(--line)}.ur-nav{display:flex;align-items:center;gap:22px;min-height:76px}.ur-logo{display:flex;align-items:center;gap:10px;font-size:23px;font-weight:900;letter-spacing:-.8px;white-space:nowrap}.ur-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;color:#fff;background:linear-gradient(135deg,#7165f4,#37c7b0);box-shadow:0 8px 20px #6558e833;font-size:19px}.ur-logo span:last-child{color:var(--brand)}.ur-links{display:flex;align-items:center;gap:21px;margin-inline-start:auto}.ur-links a{font-size:13px;font-weight:750;color:#535c75}.ur-links a:hover{color:var(--brand)}.ur-controls{display:flex;gap:8px}.ur-ghost{border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:12px;padding:9px 11px;font-weight:750;font-size:12px}.ur-hero{position:relative;overflow:hidden;padding:66px 0 54px;background:var(--hero);color:#fff}.ur-hero:before,.ur-hero:after{content:"";position:absolute;border-radius:50%;filter:blur(1px);pointer-events:none}.ur-hero:before{width:480px;height:480px;inset-inline-start:-150px;top:-240px;background:radial-gradient(circle,#6258dd66,transparent 68%)}.ur-hero:after{width:380px;height:380px;inset-inline-end:-80px;bottom:-250px;background:radial-gradient(circle,#28c7a744,transparent 70%)}.ur-hero-grid{position:relative;z-index:1;display:grid;grid-template-columns:minmax(0,1.4fr) minmax(260px,.6fr);gap:44px;align-items:center}.ur-kicker{display:inline-flex;align-items:center;gap:8px;border:1px solid #ffffff2a;border-radius:999px;padding:7px 12px;color:#d9dcff;background:#ffffff0b;font-size:12px;font-weight:800}.ur-dot{width:7px;height:7px;background:#50e2bb;border-radius:50%;box-shadow:0 0 0 4px #50e2bb22}.ur-hero h1{font-size:clamp(35px,5vw,62px);line-height:1.12;letter-spacing:-1.7px;margin:19px 0 14px;max-width:780px}.ur-hero h1 em{font-style:normal;color:#83e8ce}.ur-hero p{max-width:680px;margin:0;color:#c1c8df;font-size:17px}.ur-search{display:flex;gap:9px;margin-top:27px;padding:7px;border-radius:17px;background:#fff;box-shadow:0 16px 45px #0002;max-width:690px}.ur-search input{width:100%;min-width:0;border:0;outline:0;padding:12px 13px;color:#111831;background:transparent}.ur-search button,.ur-primary{border:0;border-radius:12px;padding:12px 19px;background:var(--brand);color:#fff;font-weight:800;white-space:nowrap}.ur-search button{background:#6558e8}.ur-search button:hover,.ur-primary:hover{background:var(--brand-dark)}.ur-trust{display:flex;flex-wrap:wrap;gap:14px;margin-top:17px;color:#c4cbe0;font-size:12px}.ur-trust span:before{content:"✓";color:#73e7c5;font-weight:900;margin-inline-end:6px}.ur-hero-panel{border:1px solid #ffffff22;border-radius:25px;padding:22px;background:linear-gradient(145deg,#ffffff14,#ffffff05);box-shadow:0 25px 70px #0002}.ur-panel-label{font-size:11px;color:#aeb8d5;font-weight:800;letter-spacing:.09em}.ur-panel-title{font-size:22px;font-weight:850;margin:8px 0 16px}.ur-mini-list{display:grid;gap:10px}.ur-mini{display:flex;align-items:center;gap:12px;border:1px solid #ffffff17;border-radius:15px;padding:11px;background:#ffffff08}.ur-mini-icon{width:39px;height:39px;display:grid;place-items:center;background:#ffffff12;border-radius:12px;font-size:18px}.ur-mini strong{display:block;font-size:13px}.ur-mini small{display:block;color:#aeb8d5;font-size:11px}.ur-section{padding:43px 0}.ur-section-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:21px}.ur-overline{color:var(--brand);font-size:11px;font-weight:900;letter-spacing:.12em}.ur-section h2{margin:4px 0 2px;font-size:clamp(24px,3vw,32px);line-height:1.25;letter-spacing:-.6px}.ur-section-head p{margin:5px 0 0;color:var(--muted);font-size:14px}.ur-category-list{display:flex;gap:8px;flex-wrap:wrap}.ur-category{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:9px 14px;color:#4f5872;font-size:12px;font-weight:800}.ur-category.active,.ur-category:hover{background:#eeedff;border-color:#d5d1ff;color:#4e42cb}.ur-tool-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.ur-card{display:flex;flex-direction:column;min-height:205px;padding:20px;background:var(--surface);border:1px solid var(--line);border-radius:19px;box-shadow:0 5px 20px #1d25500a;transition:transform .18s,border-color .18s,box-shadow .18s}.ur-card:hover{transform:translateY(-3px);border-color:#c7c3ff;box-shadow:var(--shadow)}.ur-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.ur-icon{width:45px;height:45px;border-radius:15px;display:grid;place-items:center;background:#eeedff;color:#4d40cf;font-size:21px}.ur-tag{font-size:10px;font-weight:850;color:#63708b;background:#f1f4f9;border-radius:999px;padding:5px 8px}.ur-card h3{margin:15px 0 5px;font-size:17px;line-height:1.35}.ur-card p{margin:0;color:var(--muted);font-size:13px;line-height:1.65}.ur-card-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding-top:17px;color:var(--brand);font-size:12px;font-weight:850}.ur-card-foot small{color:#8b93a8;font-weight:650}.ur-empty{grid-column:1/-1;padding:28px;border:1px dashed var(--line);border-radius:16px;text-align:center;color:var(--muted)}.ur-data-band{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:18px}.ur-feature{padding:24px;border-radius:22px;border:1px solid var(--line);background:var(--surface)}.ur-feature:first-child{background:linear-gradient(135deg,#edfff8,#fff 72%);border-color:#c7f3e3}.ur-feature .ur-icon{margin-bottom:14px}.ur-feature h3{margin:0 0 6px;font-size:19px}.ur-feature p{margin:0;color:var(--muted);font-size:13px}.ur-feature a{display:inline-block;margin-top:15px;color:var(--brand);font-weight:850;font-size:13px}.ur-seo{max-width:850px;color:#535d76;font-size:14px}.ur-seo h2{color:var(--ink);font-size:23px;margin-top:25px}.ur-faq{border-bottom:1px solid var(--line);padding:14px 0}.ur-faq summary{cursor:pointer;font-weight:800;color:var(--ink)}.ur-faq p{margin:9px 0 0;color:var(--muted)}.ur-footer{margin-top:20px;background:#0b1025;color:#c0c8df;padding:35px 0 22px}.ur-footer-grid{display:flex;justify-content:space-between;gap:28px;flex-wrap:wrap}.ur-footer p{max-width:520px;color:#9ea8c6;font-size:13px}.ur-footer-links{display:flex;gap:16px;flex-wrap:wrap;font-size:12px}.ur-copyright{border-top:1px solid #ffffff18;margin-top:24px;padding-top:16px;color:#8e99b8;font-size:11px}.ur-tool{max-width:880px;margin:32px auto;padding:clamp(18px,4vw,34px);background:var(--surface);border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow)}.ur-tool h2{font-size:clamp(24px,4vw,34px);line-height:1.2;margin:5px 0 10px}.ur-tool p{color:var(--muted)}.ur-eyebrow{font-size:11px!important;font-weight:900;letter-spacing:.12em;color:var(--brand)!important}.ur-tool label{display:block;margin:14px 0 7px;font-size:13px;font-weight:800}.ur-tool input:not([type=checkbox]),.ur-tool textarea,.ur-tool select{width:100%;min-width:0;padding:12px 13px;border:1px solid #d8deeb;border-radius:12px;background:var(--surface);color:var(--ink)}.ur-tool textarea{resize:vertical;line-height:1.6}.ur-tool input[type=checkbox]{margin-inline-end:7px}.ur-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:14px 0}.ur-actions label{display:flex;align-items:center;gap:4px;margin:0;font-weight:650}.ur-secondary{border:1px solid var(--line);border-radius:12px;padding:10px 14px;background:var(--surface);color:var(--ink);font-weight:800}.ur-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ur-note{font-size:12px!important;background:#f3f5fb;border-radius:12px;padding:12px}.ur-coming{display:inline-block;margin-top:15px;color:var(--muted);font-size:12px;font-weight:800}.ur-tool [role=status]{min-height:1.5em;font-size:13px}.blog-posts{max-width:880px;margin:30px auto;padding:0 16px}.post-outer,.post{background:var(--surface);border:1px solid var(--line);border-radius:22px;padding:clamp(18px,4vw,34px);margin-bottom:18px}.post-title{font-size:clamp(25px,4vw,36px);line-height:1.25}.post-body{overflow-wrap:anywhere}.post-body img{max-width:100%;height:auto}.post-body iframe{max-width:100%}.ur-hidden{display:none!important}.ur-load-more{display:flex;justify-content:center;margin:24px auto 0}.ur-load-more button{min-width:190px}.ur-card{will-change:transform,opacity}.ur-hero-panel{transform-origin:center}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}
html[data-theme=dark]{color-scheme:dark;--bg:#0d1222;--surface:#151c30;--ink:#edf0ff;--muted:#a6b0ca;--line:#29324a;--hero:#090d1a;--shadow:0 18px 55px #0003}html[data-theme=dark] .ur-header{background:#11172bea}html[data-theme=dark] .ur-category{color:#c1c8dd}html[data-theme=dark] .ur-category.active,html[data-theme=dark] .ur-category:hover{background:#2a2853;border-color:#5550a2;color:#e0ddff}html[data-theme=dark] .ur-tag,html[data-theme=dark] .ur-note{background:#202a42;color:#c2cce2}html[data-theme=dark] .ur-feature:first-child{background:#142b2b;border-color:#22594e}
@media(max-width:850px){.ur-hero-grid{grid-template-columns:1fr;gap:28px}.ur-hero-panel{max-width:560px}.ur-tool-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ur-links{gap:12px}.ur-nav{gap:13px}.ur-logo{font-size:21px}}@media(max-width:600px){.ur-wrap{width:min(100% - 22px,1160px)}.ur-top .ur-wrap{padding:7px 0}.ur-top span:last-child{display:none}.ur-nav{min-height:65px;flex-wrap:wrap;padding:9px 0}.ur-logo{font-size:20px}.ur-mark{width:34px;height:34px}.ur-links{order:3;width:100%;overflow:auto;padding:2px 0 5px;gap:17px}.ur-links a{white-space:nowrap;font-size:12px}.ur-controls{margin-inline-start:auto}.ur-hero{padding:43px 0 38px}.ur-hero h1{font-size:clamp(34px,10vw,47px);letter-spacing:-.8px}.ur-hero p{font-size:15px}.ur-search{gap:5px}.ur-search input{padding:10px 8px;font-size:14px}.ur-search button{padding:10px 12px;font-size:13px}.ur-hero-panel{padding:16px}.ur-section{padding:30px 0}.ur-section-head{align-items:start;flex-direction:column}.ur-tool-grid{grid-template-columns:1fr;gap:11px}.ur-card{min-height:0;padding:17px}.ur-card h3{margin-top:11px}.ur-data-band{grid-template-columns:1fr}.ur-form-grid{grid-template-columns:1fr}.ur-tool{margin:18px 11px;padding:18px;border-radius:17px}.ur-footer-grid{display:block}.ur-footer-links{margin-top:16px}.ur-actions{align-items:stretch}.ur-actions button{flex:1}.ur-category-list{gap:6px}.ur-category{padding:8px 11px}}

body.script:
(function(){
  const $=(s,r=document)=>r.querySelector(s), $=(s,r=document)=>Array.from(r.querySelectorAll(s));
  const reviewParams=new URLSearchParams(location.search);
  const userAgent=navigator.userAgent||'';
  let ownerExcluded=false;
  try{ownerExcluded=localStorage.getItem('ur-owner-exclude')==='1'}catch(e){}
  const reviewMode=reviewParams.has('utilityra_review')||reviewParams.has('preview')||navigator.webdriver||/bot|crawler|spider|headless|playwright|puppeteer|lighthouse|google-inspectiontool|chatgpt|openai|anthropic|claude|perplexity|gemini|bingpreview/i.test(userAgent);
  const apiBase=String(window.UTILITYRA_API_BASE||'').replace(/\\/$/,'');
  let visitorKey='';
  try{visitorKey=sessionStorage.getItem('ur-visitor-key')||'';if(!visitorKey){visitorKey=(crypto.randomUUID?crypto.randomUUID():String(Date.now())+'-'+Math.random().toString(36).slice(2));sessionStorage.setItem('ur-visitor-key',visitorKey)}}catch(e){}
  function sendEvent(eventType,extra={}){
    if(!apiBase||!visitorKey||ownerExcluded||reviewMode||document.querySelector('.ur-admin'))return;
    const payload={visitorKey,eventType,path:location.pathname.slice(0,180),toolKey:extra.toolKey||'',searchTerm:extra.searchTerm||'',referrer:document.referrer||'',reviewMode:false};
    fetch(apiBase+'/api/analytics/event',{method:'POST',mode:'cors',headers:{'content-type':'application/json'},body:JSON.stringify(payload),keepalive:true}).catch(()=>{});
  }
  const toolRoot=$('.ur-tool');
  const currentTool=toolRoot?(toolRoot.dataset.toolId||location.pathname.split('/').pop().replace(/\\.html$/,'').replace(/-utilityra$/,'')):'';
  if(toolRoot){sendEvent('page_view');sendEvent('tool_open',{toolKey:currentTool});toolRoot.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&b.type!=='reset'&&!/clear|copy|download/i.test((b.id||'')+' '+(b.textContent||'')))sendEvent('tool_action',{toolKey:currentTool})})}
  else if(location.pathname==='/'||location.pathname==='/index.html')sendEvent('page_view');
  if(location.pathname==='/'||location.pathname==='/index.html'){
    $('#ur-search-form')?.addEventListener('submit',()=>{const term=($('#ur-search')?.value||'').trim();if(term){const visible=$('.ur-card').some(card=>!card.classList.contains('ur-hidden'));sendEvent(visible?'search':'search_miss',{searchTerm:term})}});
  }
  const reduceMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function animatePage(){
    if(reduceMotion)return;
    if(window.gsap){
      const gs=window.gsap;
      if($('.ur-hero h1'))gs.from('.ur-hero .ur-kicker',{y:12,opacity:0,duration:.45,ease:'power2.out'});
      if($('.ur-hero h1'))gs.from('.ur-hero h1',{y:24,opacity:0,duration:.65,delay:.08,ease:'power3.out'});
      if($('.ur-hero p'))gs.from('.ur-hero p',{y:15,opacity:0,duration:.5,delay:.16,ease:'power2.out'});
      if($('.ur-search'))gs.from('.ur-search',{y:12,opacity:0,duration:.5,delay:.22,ease:'power2.out'});
      if($('.ur-hero-panel'))gs.from('.ur-hero-panel',{x:24,opacity:0,duration:.7,delay:.1,ease:'power3.out'});
      const heads=$('.ur-section-head');
      if('IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){gs.fromTo(entry.target,{y:14,opacity:0},{y:0,opacity:1,duration:.45,ease:'power2.out',clearProps:'transform'});io.unobserve(entry.target)}}),{threshold:.12});heads.forEach(el=>io.observe(el))}
      gs.utils.toArray('.ur-feature,.ur-mini').forEach((el,i)=>{if(i<10)gs.fromTo(el,{opacity:0,y:10},{opacity:1,y:0,duration:.4,delay:i*.035,scrollTrigger:undefined,clearProps:'transform'})});
    }else{
      $('.ur-hero .ur-kicker,.ur-hero h1,.ur-hero p,.ur-search,.ur-hero-panel').forEach((el,i)=>{el.style.animation='urFadeUp .55s ease '+(i*.07)+'s both'});
    }
  }
  animatePage();
  const root=document.documentElement;
  const storedTheme=(()=>{try{return localStorage.getItem('ur-theme')}catch(e){return null}})();
  if(storedTheme==='dark')root.setAttribute('data-theme','dark');
  $('#ur-theme')?.addEventListener('click',()=>{const dark=root.getAttribute('data-theme')!=='dark';if(dark)root.setAttribute('data-theme','dark');else root.removeAttribute('data-theme');try{localStorage.setItem('ur-theme',dark?'dark':'light')}catch(e){}});
  let language='ar';
  function setLanguage(next){language=next;root.lang=next;root.dir=next==='ar'?'rtl':'ltr';$$('[data-en][data-ar]').forEach(el=>{el.textContent=next==='ar'?el.dataset.ar:el.dataset.en});$$('[data-en-html][data-ar-html]').forEach(el=>{el.innerHTML=next==='ar'?el.dataset.arHtml:el.dataset.enHtml});const search=$('#ur-search');if(search){search.placeholder=next==='ar'?'ابحث عن أداة، مثل JSON أو كلمة أو نسبة مئوية':'Search for a tool, e.g. JSON, words or percentage';search.setAttribute('aria-label',next==='ar'?'ابحث عن أداة':'Search tools')}const btn=$('#ur-language');if(btn)btn.textContent=next==='ar'?'EN':'عربي';renderCategories(activeCategory);filterTools()}
  $('#ur-language')?.addEventListener('click',()=>setLanguage(language==='ar'?'en':'ar'));
  const cards=$('.ur-card');const cats=[...new Set(cards.map(c=>c.dataset.cat))];let activeCategory='all';let expanded=false;const initialLimit=12;
  function renderCategories(active){const wrap=$('#ur-categories');if(!wrap)return;const labels=language==='ar'?{'all':'كل الأدوات','Text':'النصوص','Developer':'المطورين','Data':'البيانات','Privacy':'الخصوصية','Time':'الوقت','Calculators':'الحاسبات','Image':'الصور','Study':'الدراسة','Office':'المكاتب','Design':'التصميم'}:{'all':'All tools','Text':'Text','Developer':'Developer','Data':'Data','Privacy':'Privacy','Time':'Time','Calculators':'Calculators','Image':'Image','Study':'Study','Office':'Office','Design':'Design'};wrap.innerHTML=[['all',labels.all],...cats.map(c=>[c,labels[c]||c])].map(([key,label])=>'<button type="button" class="ur-category '+(active===key?'active':'')+'" data-category="'+key+'">'+label+'</button>').join('')}
  function filterTools(){const q=($('#ur-search')?.value||'').trim().toLocaleLowerCase();const matched=cards.filter(c=>{const matchesCat=activeCategory==='all'||c.dataset.cat===activeCategory;return matchesCat&&(!q||(c.innerText+' '+c.dataset.search+' '+c.dataset.id+' '+(c.dataset.arCat||'')).toLocaleLowerCase().includes(q))});const count=matched.length;const limit=expanded||q||activeCategory!=='all'?count:initialLimit;cards.forEach(c=>c.classList.toggle('ur-hidden',matched.indexOf(c)===-1||matched.indexOf(c)>=limit));const more=$('#ur-load-more');if(more)more.classList.toggle('ur-hidden',count<=limit);if(more)more.querySelector('button').textContent=language==='ar'?'عرض المزيد من الأدوات':'Show more tools';const note=$('#ur-results-note');if(note)note.textContent=language==='ar'?(count?'عدد الأدوات المطابقة: '+count:'لا توجد نتائج. جرّب كلمات بحث أخرى.'):(count+' matching tools.');}
  $('#ur-categories')?.addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;activeCategory=b.dataset.category;expanded=false;renderCategories(activeCategory);filterTools()});
  $('#ur-load-more')?.addEventListener('click',()=>{expanded=true;filterTools()});
  $('#ur-search')?.addEventListener('input',()=>{activeCategory='all';expanded=false;renderCategories(activeCategory);filterTools()});
  $('#ur-search-form')?.addEventListener('submit',e=>{e.preventDefault();$('#tools')?.scrollIntoView({behavior:'smooth',block:'start'});filterTools()});
  $('#ur-year').textContent=String(new Date().getFullYear());
  renderCategories(activeCategory);filterTools();
})();
